#ifndef MEP_NIM_LSP_H
#define MEP_NIM_LSP_H

// The analysis half of mep's own Nim language server (the wire half is
// nim_lsp_server.cpp, the `mep-nim-lsp` binary; the `nim_ls` entry
// in main.cpp's kBuiltinLsp spawns it). Everything here is a pure function
// of the document text, so the whole server is testable without a client
// (nim_lsp_test.cpp). Positions are 0-based lines and 0-based byte
// columns (`positionEncoding: "utf-8"`).
//
// Generated by tools/new_language.py; nix_lsp.h is the worked example of
// every function below.

#include <memory>
#include <string>
#include <vector>

struct NimLspRange {
    int line = 0, col = 0, end_line = 0, end_col = 0;
};

class NimLspDocument;

/** @brief Parses and analyses a document; every query below runs on the result. */
std::shared_ptr<const NimLspDocument> NimLspAnalyze(const std::vector<std::string> &lines);

// --- Diagnostics ------------------------------------------------------------------

enum class NimLspSeverity { Error = 1, Warning = 2, Information = 3, Hint = 4 };

struct NimLspDiagnostic {
    NimLspRange range;
    NimLspSeverity severity = NimLspSeverity::Error;
    std::string code;  // stable id: syntax-error, ...
    std::string message;
    bool unnecessary = false;  // LSP DiagnosticTag.Unnecessary
    bool deprecated = false;   // LSP DiagnosticTag.Deprecated
};

std::vector<NimLspDiagnostic> NimLspDiagnostics(const NimLspDocument &doc);
/** @brief `path:line:col: severity: message [code]`, 1-based, as `--lint` prints it. */
std::string NimLspFormatDiagnostic(const std::string &path, const NimLspDiagnostic &d);
/** @brief Whether a diagnostic makes `--lint` exit non-zero (an error or a warning). */
bool NimLspDiagnosticFails(const NimLspDiagnostic &d);

// --- Completion / hover / signature help -------------------------------------------

enum class NimLspKind {
    Text = 1, Method = 2, Function = 3, Field = 5, Variable = 6, Class = 7, Module = 9, Property = 10,
    Value = 12, Keyword = 14, Snippet = 15, Constant = 21, Struct = 22,
};

struct NimLspCompletionItem {
    std::string label;
    std::string insert_text;
    NimLspKind kind = NimLspKind::Text;
    std::string detail;
    std::string documentation;
    int replace_start = 0, replace_end = 0;  // byte columns on the request's line
};

std::vector<NimLspCompletionItem> NimLspCompletions(const NimLspDocument &doc, int line, int col);

struct NimLspHoverInfo {
    bool found = false;
    std::string text;  // markdown
    NimLspRange range;
};

NimLspHoverInfo NimLspHover(const NimLspDocument &doc, int line, int col);

struct NimLspSignatureHelp {
    bool found = false;
    std::string label;
    std::vector<std::string> params;  // substrings of label
    std::string documentation;
    int active_param = 0;
};

NimLspSignatureHelp NimLspSignatureAt(const NimLspDocument &doc, int line, int col);

// --- Navigation -------------------------------------------------------------------------

struct NimLspLocation {
    NimLspRange range;
};

std::vector<NimLspLocation> NimLspDefinition(const NimLspDocument &doc, int line, int col);

struct NimLspReference {
    NimLspRange range;
    bool is_definition = false;
};

std::vector<NimLspReference> NimLspReferences(const NimLspDocument &doc, int line, int col);

struct NimLspTextEdit {
    NimLspRange range;
    std::string new_text;
};

struct NimLspRenameTarget {
    bool found = false;
    NimLspRange range;
    std::string placeholder;
};

NimLspRenameTarget NimLspPrepareRename(const NimLspDocument &doc, int line, int col);
std::vector<NimLspTextEdit> NimLspRename(const NimLspDocument &doc, int line, int col,
                                               const std::string &new_name, std::string *error);

// --- Outline / folding --------------------------------------------------------------------

enum class NimLspSymbolKind {
    File = 1, Module = 2, Namespace = 3, Class = 5, Method = 6, Property = 7, Field = 8, Function = 12,
    Variable = 13, Constant = 14, String = 15, Number = 16, Boolean = 17, Array = 18, Object = 19, Key = 20,
    Null = 21,
};

struct NimLspSymbol {
    std::string name;
    std::string detail;
    NimLspSymbolKind kind = NimLspSymbolKind::Variable;
    NimLspRange range;
    NimLspRange sel_range;
    int parent = -1;
};

std::vector<NimLspSymbol> NimLspSymbols(const NimLspDocument &doc);

struct NimLspFold {
    int start_line = 0, end_line = 0;
    std::string kind;  // "" or "comment"
};

std::vector<NimLspFold> NimLspFolds(const NimLspDocument &doc);

// --- Formatting ------------------------------------------------------------------------------

/** @brief The formatter as one edit over the changed lines; none when already formatted. */
std::vector<NimLspTextEdit> NimLspFormat(const std::vector<std::string> &lines, int width, std::string *error);

#endif  // MEP_NIM_LSP_H
